import itertools
import json

def solve_puzzle():
    # Define puzzle parameters
    houses = [1, 2, 3, 4]
    names = ["Arnold", "Peter", "Eric", "Alice"]
    styles = ["victorian", "ranch", "colonial", "craftsman"]

    solutions = []

    # Iterate over all permutations of names and styles
    for name_perm in itertools.permutations(names):
        # Clue 3: Eric is in the third house (house index 2)
        if name_perm[2] != "Eric":
            continue
        # Clue 4: Arnold is in the fourth house (house index 3)
        if name_perm[3] != "Arnold":
            continue

        for style_perm in itertools.permutations(styles):
            # Clue 2: Ranch is directly left of Victorian
            idx_ranch = style_perm.index("ranch")
            if idx_ranch == len(houses) - 1:
                continue
            if style_perm[idx_ranch + 1] != "victorian":
                continue

            # Clue 1: Eric is in a Craftsman-style house
            if name_perm.index("Eric") != style_perm.index("craftsman"):
                continue

            # Clue 5: The person in a Victorian house is Alice
            if name_perm[style_perm.index("victorian")] != "Alice":
                continue

            # All constraints satisfied; record solution
            solution_rows = []
            for h in houses:
                solution_rows.append([str(h), name_perm[h - 1], style_perm[h - 1]])
            solutions.append(solution_rows)

    # Choose the first solution (puzzle is expected to be unique)
    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")
    final_rows = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "HouseStyle"],
            "rows": final_rows
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
